import { useState, useRef } from 'react';

/**
 * Hook de reconocimiento de voz seguro (SpeechRecognition).
 * - Verifica disponibilidad real de la API
 * - Usa 'new' de forma segura (try/catch)
 * - Evita crash en entornos Hermes/Web donde SpeechRecognition no está implementado
 * - Incluye logs claros para depuración
 */
export function useSpeechRecognition(onResult: (text: string) => void) {
  const [listening, setListening] = useState(false);
  const [supported, setSupported] = useState(
    typeof window !== 'undefined' &&
      ((window as any).SpeechRecognition || (window as any).webkitSpeechRecognition)
  );
  const recognitionRef = useRef<any>(null);

  const startListening = () => {
    if (typeof window === 'undefined') return;

    const SpeechRecognitionCtor: any =
      (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

    if (!SpeechRecognitionCtor) {
      console.warn('❌ SpeechRecognition API no soportada en este navegador o entorno.');
      setSupported(false);
      return;
    }

    // Si había una instancia anterior, abortarla
    if (recognitionRef.current) {
      try {
        recognitionRef.current.abort();
      } catch {}
      recognitionRef.current = null;
    }

    let recognition: any;
    try {
      recognition = new SpeechRecognitionCtor(); // aseguramos uso de 'new'
    } catch (err) {
      console.error('⚠️ Error creando SpeechRecognition:', err);
      setSupported(false);
      return;
    }

    recognition.lang = 'es-ES';
    recognition.continuous = false;
    recognition.interimResults = false;

    let gotResult = false;
    let timeoutHandle: any;

    recognition.onstart = () => {
      console.info('🎙️ Reconocimiento iniciado');
      setListening(true);
      gotResult = false;
    };

    recognition.onspeechstart = () => {
      console.info('🎤 Se detectó voz');
    };

    recognition.onspeechend = () => {
      console.info('🔇 Fin de voz detectada (esperando resultado)');
      // Delay de 800ms para permitir resultado
      timeoutHandle = setTimeout(() => {
        if (!gotResult) {
          console.warn('⚠️ No se recibió resultado, reiniciando...');
          try {
            recognition.stop();
          } catch {}
          startListening(); // reintento automático
        }
      }, 800);
    };

    recognition.onresult = (event: any) => {
      gotResult = true;
      clearTimeout(timeoutHandle);
      const text = event.results[0][0].transcript.toLowerCase();
      console.info('✅ Texto reconocido:', text);
      onResult(text);
      try {
        recognition.stop();
      } catch {}
    };

    recognition.onnomatch = () => {
      console.warn('🤔 No se reconoció ninguna palabra');
    };

    recognition.onerror = (e: any) => {
      clearTimeout(timeoutHandle);
      console.error('⚠️ Error de reconocimiento:', e.error);
      if (e.error === 'not-allowed' || e.error === 'service-not-allowed') {
        alert('No se puede acceder al micrófono. Revisa los permisos del navegador.');
      }
      setListening(false);
    };

    recognition.onend = () => {
      console.info('🛑 Reconocimiento finalizado');
      clearTimeout(timeoutHandle);
      setListening(false);
    };

    recognitionRef.current = recognition;

    try {
      recognition.start();
    } catch (err) {
      console.error('⚠️ Error al iniciar reconocimiento:', err);
    }
  };

  const stopListening = () => {
    if (!recognitionRef.current) return;
    try {
      recognitionRef.current.stop();
    } catch {}
    setListening(false);
  };

  return { listening, supported, startListening, stopListening };
}
